const DKEY_ART=Object.freeze(["@@LOCAL:kw_dungeon_key_00.webp@@","@@LOCAL:kw_dungeon_key_01.webp@@","@@LOCAL:kw_dungeon_key_02.webp@@","@@LOCAL:kw_dungeon_key_03.webp@@","@@LOCAL:kw_dungeon_key_04.webp@@","@@LOCAL:kw_dungeon_key_05.webp@@","@@LOCAL:kw_dungeon_key_06.webp@@","@@LOCAL:kw_dungeon_key_07.webp@@","@@LOCAL:kw_dungeon_key_08.webp@@","@@LOCAL:kw_dungeon_key_09.webp@@","@@LOCAL:kw_dungeon_key_10.webp@@","@@LOCAL:kw_dungeon_key_11.webp@@","@@LOCAL:kw_dungeon_key_12.webp@@","@@LOCAL:kw_dungeon_key_13.webp@@"]);
function dungeonKeyIndex(k){const m=typeof k==='string'&&k.match(/^dungeon-key-(\d+)$/);const n=m?Number(m[1]):-1;return n>=0&&n<zones.length?n:-1}
function isDungeonKey(i){return dungeonKeyIndex(i?.material)>=0}
function dungeonKeyArt(n){return DKEY_ART[n]??''}
function dungeonKeyDef(k){const n=dungeonKeyIndex(k);return n<0?undefined:{id:k,art:dungeonKeyArt(n),n:['Schlüssel: '+zones[n][0],'Dungeon key: '+zones[n][0],'Ключ: '+zones[n][0]],d:['Einmal verwenden, um dieses Verlies dauerhaft freizuschalten.','Use once to permanently unlock this dungeon.','Используй один раз, чтобы открыть подземелье навсегда.']}}
function keyPending(){if(!Array.isArray(s.pendingDungeonKeys))s.pendingDungeonKeys=[];return s.pendingDungeonKeys}
function hasDungeonKey(n){return s.bag.some(i=>dungeonKeyIndex(i.material)===n)||keyPending().includes(n)}
function deliverPendingDungeonKeys(){const p=keyPending();for(let j=0;j<p.length;){const n=p[j];if(!zones[n]||s.keys[n]||s.bag.some(i=>dungeonKeyIndex(i.material)===n)){p.splice(j,1);continue}if(s.bag.length>=BAG_CAP)break;s.bag.push({id:uid(),material:'dungeon-key-'+n,qty:1,locked:true});p.splice(j,1)}}
function grantDungeonKey(n){if(!zones[n]||s.keys[n]||hasDungeonKey(n))return false;keyPending().push(n);deliverPendingDungeonKeys();return true}
function useInventoryItem(id){if(battle?.running)return false;const i=s.bag.find(x=>x.id===id);const n=dungeonKeyIndex(i?.material);if(n<0||s.keys[n]||s.level<zones[n][1]||(n>0&&s.d[n-1]<zones[n-1][2].length))return false;s.keys[n]=true;s.bag=s.bag.filter(x=>x!==i);closeItem();AudioGame.fx('key');note(hubLabel('Dungeon freigeschaltet: ','Dungeon unlocked: ','Подземелье открыто: ')+zones[n][0]);dungeonMode='story';dungeonList=false;dp=n;page='Dungeons';render();return true}
function dungeonKeyDetail(i){const n=dungeonKeyIndex(i.material);const ready=!s.keys[n]&&s.level>=zones[n][1]&&(n===0||s.d[n-1]>=zones[n-1][2].length);$('modal').hidden=false;$('modal').innerHTML='<div class="sheet"><div class="row"><b>'+hubLabel('Verwendbarer Schlüssel','Usable key','Ключ')+'</b><button class="close" onclick="closeItem()">×</button></div><div class="itemintro"><img src="'+dungeonKeyArt(n)+'"><h3>'+materialName(i.material)+'</h3></div><p>'+hubLabel(...dungeonKeyDef(i.material).d)+'</p><small>'+hubLabel('Questgegenstand · nicht verkäuflich','Quest item · cannot be sold','Квестовый предмет · не продаётся')+'</small><button class="primary" onclick="useInventoryItem(&quot;'+i.id+'&quot;)" '+(ready?'':'disabled')+'>'+hubLabel('Schlüssel verwenden','Use key','Использовать ключ')+'</button></div>'}

const STACK_CAP=999;
const MATERIAL_GATES={scrap:1,bolts:1,rubber:1,tape:1,electronics:8,wire:8,oil:8,precision:25};
function materialPool(level){return MATERIALS.filter(m=>level>=MATERIAL_GATES[m.id])}
function canAddOneMaterial(k){let i={material:k};return inventoryStoreRoom(i,s.bag,BAG_CAP)>0||(inventoryMoveMatches(i)&&inventoryStoreRoom(i,hqState().warehouse,warehouseCap())>0)}

function isMaterial(i){return isDungeonKey(i)||!!i&&MATERIALS.some(m=>m.id===i.material)}
function materialDef(k){return dungeonKeyDef(k)||MATERIALS.find(m=>m.id===k)}
function materialName(k){let m=materialDef(k);return m?hubLabel(...m.n):k}
function materialArt(k){let m=materialDef(k);return m?.art||itemArt({a:0})}
function craftingEntries(){return [...(s.hq?.warehouse||[]),...s.bag].filter(i=>!i.locked)}
function materialCount(k){return craftingEntries().reduce((n,i)=>n+(i.material===k?i.qty:0),0)}
function addMaterial(k,n){if(s.level<20&&gemData(k))return 0;if(!materialDef(k)||!Number.isSafeInteger(n)||n<=0)return 0;let remaining=n;if(inventoryMoveMatches({material:k}))remaining-=inventoryInsertStack(hqState().warehouse,warehouseCap(),k,remaining);if(remaining)remaining-=inventoryInsertStack(s.bag,BAG_CAP,k,remaining);return n-remaining}

function consumeMaterials(req){if(!Object.entries(req).every(([k,n])=>Number.isSafeInteger(n)&&n>=0&&materialCount(k)>=n))return false;for(let [k,n] of Object.entries(req)){for(let i of craftingEntries()){if(i.material!==k||!n)continue;let take=Math.min(n,i.qty);i.qty-=take;n-=take}}s.bag=s.bag.filter(i=>!isMaterial(i)||i.qty>0);if(s.hq?.warehouse)s.hq.warehouse=s.hq.warehouse.filter(i=>!isMaterial(i)||i.qty>0);return true}
function materialSlot(i,fn){if(isDungeonKey(i))return `<button class="slot filled materialSlot" style="--r:#e8b84b" aria-label="${materialName(i.material)}" ${fn?`onclick="${fn}"`:''}><img alt="" src="${materialArt(i.material)}"><span class="rank">K</span></button>`;return `<button class="slot filled materialSlot" style="--r:#b9a77e" aria-label="${materialName(i.material)} × ${i.qty}" ${fn?`onclick="${fn}"`:''}><img alt="" src="${materialArt(i.material)}"><span class="rank">M</span><span class="il materialQty">×${i.qty}</span></button>`}
function materialDetail(i){if(isDungeonKey(i))return dungeonKeyDetail(i);let m=materialDef(i.material);$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet"><div class="row"><b>${hubLabel('Crafting-Material','Crafting material','Материал для ремесла')}</b><button class="close" onclick="closeItem()">×</button></div><div class="itemintro"><img src="${materialArt(m.id)}"><h3>${materialName(m.id)}</h3></div><p>${hubLabel(...m.d)}</p><p>${hubLabel('Im Stapel','In stack','В стопке')}: ${i.qty}/${STACK_CAP} · ${hubLabel('Verfügbar','Available','Доступно')}: ${materialCount(m.id)}</p><small>${hubLabel('Für Garage, Fahrzeugausbau und zukünftige Rezepte. Nicht ausrüstbar.','For garage and vehicle upgrades and future recipes. Cannot be equipped.','Для гаража, улучшений транспорта и будущих рецептов. Не экипируется.')}</small>${inventoryItemActions(i)}</div>`}
function grantBattleMaterials(b){if(!b.win||b.o.arena)return;let l=b.o.l||1,pool=materialPool(l);let chance=b.o.d!==undefined?.85:b.o.event?.25:b.o.tower?.40:b.o.cost===15?.65:b.o.cost===10?.40:.25;if(!battleDropRoll(chance,b))return;let m=pick(pool),n=b.o.d!==undefined?range(1,3):b.o.cost===15?range(1,2):1,added=addMaterial(m.id,n);if(added){b.materialDrop={id:m.id,qty:added};battleLog(b,hubLabel('Material gefunden: ','Material found: ','Найден материал: ')+materialName(m.id)+' ×'+added,'outgoing')}if(added<n)battleLog(b,hubLabel('Kein Platz für weitere Materialien.','No room for more materials.','Нет места для материалов.'),'system')}

let settingsReturn51='Held';const settingsPages51=['Mehr','Profile','Admin','Audio'];let shopReturn52='Held';function openShop52(){if(battle?.running||onboard52)return;if(page==='Kristallshop'){closeShop52();return}shopReturn52=page;go('Kristallshop')}function closeShop52(){go(shopReturn52==='Kampf'?'Held':shopReturn52)}
