function kwWeaponAffixHint(key){const row=[["pctPoison","3 Runden je 8 % des auslösenden Treffers.","3 rounds at 8% of the triggering hit each.","3 раунда по 8 % от вызвавшего эффект удара."],["pctFire","2 Runden je 14 % des auslösenden Treffers.","2 rounds at 14% of the triggering hit each.","2 раунда по 14 % от вызвавшего эффект удара."],["pctFrost","2 Runden: −10 % Angriff und halbierte Ausweichchance.","2 rounds: −10% attack and half dodge chance.","2 раунда: −10 % атаки и вдвое меньше шанс уклонения."],["pctLightning","Sofort 20 % zusätzlichen Schaden des auslösenden Treffers.","Immediately deals 20% extra damage based on the triggering hit.","Мгновенно наносит 20 % дополнительного урона от вызвавшего эффект удара."],["pctHoly","Heilt um 15 % des auslösenden Schadens.","Heals for 15% of the triggering damage.","Восстанавливает 15 % от вызвавшего эффект урона."],["pctShadow","2 Runden: Ziel erleidet 10 % mehr direkten Schaden.","2 rounds: target takes 10% more direct damage.","2 раунда: цель получает на 10 % больше прямого урона."],["pctArcane","Der nächste direkte Treffer verursacht 15 % weniger Schaden; verfällt nach der nächsten eigenen Aktion.","Next direct hit deals 15% less damage; expires after your next action.","Следующий прямой удар наносит на 15 % меньше урона; исчезает после следующего собственного действия."]].find(r=>r[0]===key);return row?'<small>'+hubLabel(...row.slice(1))+'</small>':''}
