function inspectAffixes(kind,id){let i=kind==='shop'?s.shop[id]?.i:s.bag.find(x=>x.id===id)||s.eq.find(x=>x?.id===id);if(!i)return;let back=kind==='shop'?`shopDetail(${id})`:`showItem('${id}')`;let line=(label,value)=>value?`<div class="affixLine"><span>${label}</span><b>${value}</b></div>`:'';let imp=i.implicit;let base=imp?[...imp.v.map((v,k)=>line(attrs[k],v)),line('Schaden',imp.atk),line('Rüstung',imp.def),line('Leben',imp.hp),line('Kritbonus',imp.crit?Math.round(imp.crit*100)+' %':'')].join(''):'';let mods=i.mods||[];let group=(k,title)=>`<div class="affixGroup"><b>${title} · ${mods.filter(m=>affixDefs[m.i]?.[1]===k).length}/${myth47(i)?4:3}</b>${mods.filter(m=>affixDefs[m.i]?.[1]===k).map(m=>{let d=affixDefs[m.i],lo=affixValue(d,i.l,(i.r===6?4:i.r),m.tier,.85,m.tierScale===2?2:1),hi=affixValue(d,i.l,(i.r===6?4:i.r),m.tier,1.15,m.tierScale===2?2:1);return `<div class="affixMod"><span class="tier t${m.tier}" title="${m.tierScale===2?hubLabel('Ab Stufe','From level','С уровня')+' '+affixTierGate(m.tier):hubLabel('Altes Tier-System','Legacy tier system','Старая система тиров')}">T${m.tier}</span><div><strong>${d[0]}</strong><span>${affixText(d,m.value)}</span>${affixSecondaryText(d,m.value)}${kwWeaponAffixHint(d[2])}${m.effectGate>1?`<small>${hubLabel('Effekt ab Level','Effect from level','Эффект с уровня')} ${m.effectGate}</small>`:''}${m.tierScale===2?'':`<small>${hubLabel('Alter Tier-Roll','Legacy tier roll','Старый тир')}</small>`}<small>Roll ${Math.round(m.roll*100)} % · ${d[2]==='crit'||d[2].startsWith('pct')?(lo*100).toFixed(2)+'–'+(hi*100).toFixed(2)+' %':fmt(lo)+'–'+fmt(hi)}</small></div></div>`}).join('')||'<small>Keine Modifikatoren</small>'}</div>`;$('modal').hidden=false;$('modal').innerHTML=`<div class="sheet affixSheet" style="--r:${qualityColor52(i)}"><div class="row"><b>Modifikatoren · iLvl ${num(i.l)}</b><button class="close" onclick="${back}">‹</button></div><div class="itemintro"><img src="${itemArt(i)}"><h3 style="color:${qualityColor52(i)}">${name(i)}</h3></div>${weaponItemMarkup(i)}${imp?`<div class="affixGroup"><b>Grundbonus (implizit)</b>${base||'<small>Kein Grundbonus</small>'}</div>${group('P','Präfixe')}${group('S','Suffixe')}`:`<div class="affixGroup"><b>Altbestand · v0.13 oder älter</b><small>Bestehende Werte wurden unverändert übernommen. Neue Funde besitzen Tiers und Rollbereiche.</small>${i.v.map((v,j)=>line(attrs[j],v)).join('')}${line('Schaden',i.atk)}${line('Rüstung',i.def)}${line('Leben',i.hp)}${line('Kritbonus',i.crit?Math.round(i.crit*100)+' %':'')}</div>`}<button class="primary" onclick="${back}">‹ Zurück zum Gegenstand</button></div>`}
